<?php

namespace App\Enums;

/**
 * Where a metadata field of a work came from (assets.metadata_sources).
 */
enum MetadataSource: string
{
    /** Read from the uploaded file (IPTC/XMP): wins over generation. */
    case File = 'file';

    /** Generated by the model; replaced by a later generation. */
    case Ai = 'ai';

    /** Edited by the user: generation never touches it without the user's action. */
    case User = 'user';
}
